checks.probe_source:
extends SceneTree

func _initialize() -> void:
	_verify_shell.call_deferred()

func _verify_shell() -> void:
	var scene_error: Error = change_scene_to_file("res://scenes/bootstrap.tscn")
	if scene_error != OK:
		push_error("Cannot load bootstrap.")
		quit(1)
		return
	for frame: int in range(10):
		await process_frame
		if current_scene is Control:
			break
	if not current_scene is Control or current_scene.name != "ClientShell":
		push_error("Bootstrap did not select the Control client shell.")
		quit(1)
		return
	var label: Node = current_scene.get_node("CenterContainer/VBoxContainer/BaselineLabel")
	var button: Node = current_scene.get_node("CenterContainer/VBoxContainer/QuitButton")
	if not label is Label or label.text != "Briarwake client baseline":
		push_error("Baseline label is missing or wrong.")
		quit(1)
		return
	if not button is Button or button.text != "Quit" or not button.pressed.is_connected(current_scene._on_quit_button_pressed):
		push_error("Quit button is missing or disconnected.")
		quit(1)
		return
	var descendants: Array[Node] = current_scene.find_children("*", "", true, false)
	if descendants.size() != 4:
		push_error("Unexpected client scene contents.")
		quit(1)
		return
	for descendant: Node in descendants:
		if not descendant is Control:
			push_error("Client shell contains a non-UI node.")
			quit(1)
			return
	print("PASS: Bootstrap selected isolated shell with expected label and connected Quit button; only four UI descendants.")
	create_timer(2.0).timeout.connect(_quit_failed)
	print("Emitting the real Quit button pressed signal; expected process exit 0.")
	button.pressed.emit()

func _quit_failed() -> void:
	push_error("Quit button failed to end the process.")
	quit(1)
